begin;
alter table public.policies add column week_start_dow smallint check(week_start_dow between 0 and 6),add column week_cutoff time,add column timezone text not null default 'Asia/Tehran' check(timezone='Asia/Tehran');
create function public.compute_week_deadline(p_event_time timestamptz,p_policy uuid) returns timestamptz language plpgsql stable security definer set search_path='' as $$ declare pol public.policies;local_day date;days_since integer;begin select * into pol from public.policies where id=p_policy and approved;if not found or pol.week_start_dow is null or pol.week_cutoff is null then raise exception 'weekly deadline policy pending';end if;local_day:=(p_event_time at time zone pol.timezone)::date;days_since:=((extract(dow from local_day)::integer-pol.week_start_dow+7)%7);return ((local_day-days_since+6)+pol.week_cutoff) at time zone pol.timezone;end; $$;
create function public.guard_event_deadline() returns trigger language plpgsql security definer set search_path='' as $$ declare expected timestamptz;begin if new.status='published' and new.club_approved then expected:=public.compute_week_deadline(new.ends_at,new.policy_id);if new.summary_deadline is distinct from expected then raise exception 'deadline must match approved week policy';end if;end if;return new;end; $$;
create trigger event_deadline before insert or update on public.events for each row execute function public.guard_event_deadline();
create function public.set_week_policy(p_policy uuid,p_start integer,p_cutoff time,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_role('admin') or length(p_reason)<5 then raise exception 'global academic authority and reason required';end if;if exists(select 1 from public.events where policy_id=p_policy and status='published') then raise exception 'create a new policy version';end if;perform set_config('utr.reason',p_reason,true);update public.policies set week_start_dow=p_start,week_cutoff=p_cutoff where id=p_policy;end; $$;
revoke all on function public.compute_week_deadline(timestamptz,uuid),public.guard_event_deadline(),public.set_week_policy(uuid,integer,time,text) from public,anon;
grant execute on function public.compute_week_deadline(timestamptz,uuid),public.set_week_policy(uuid,integer,time,text) to authenticated;
commit;
